      const renderCanvas = document.createElement('canvas');
      /* 固定 16:9，宽度按设置里的档位（2K 2560 / 4K 3840）；窗口比例变化时不再重算高度，
         避免画面被拉伸，显示交给 CSS contain。 */
      const renderW = bootRenderWidth();
      const renderH = Math.round(renderW * 9 / 16);
      renderCanvas.width = renderW;
      renderCanvas.height = renderH;

      const displayCanvas = document.createElement('canvas');
      displayCanvas.width = renderW;
      displayCanvas.height = renderH;
      /* contain 居中：宽窗口时左右留黑，窄窗口时上下留黑，比例始终 16:9 */
      displayCanvas.style.cssText = 'display:block;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(100vw, calc(100vh * 16 / 9));height:auto;background:#000';
      host.appendChild(displayCanvas);
      (document.body || document.documentElement).appendChild(host);

      /* 画布尺寸固定，跟窗口大小无关；缩放交给 CSS 的 contain */
      const sizeDisplay = () => {};

